RRB.load({"id": "gd-full-6", "exam": "gd", "label": "Group D full mock 6 (100 Q)", "questions": [{"s": "General Science", "t": "Biology", "q": "Which of these is a mammal?", "o": ["Shark", "Penguin", "Crocodile", "Whale"], "a": 3, "e": "Whales breathe air with lungs, are warm-blooded and feed their young on milk; a shark is a fish and a penguin is a bird.", "qh": "इनमें से कौन स्तनधारी है?", "oh": ["शार्क", "पेंगुइन", "मगरमच्छ", "व्हेल"], "eh": "व्हेल फेफड़ों से साँस लेती है, गर्म खून वाली है और बच्चों को दूध पिलाती है; शार्क मछली और पेंगुइन पक्षी है।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Solder, used to join electrical wires, is an alloy of:", "o": ["Copper and zinc", "Iron and carbon", "Tin and lead", "Copper and tin"], "a": 2, "e": "Traditional solder is tin + lead with a low melting point; copper + zinc is brass.", "qh": "बिजली के तार जोड़ने में इस्तेमाल होने वाला सोल्डर किसकी मिश्रधातु है?", "oh": ["तांबा और जस्ता", "लोहा और कार्बन", "टिन और सीसा", "तांबा और टिन"], "eh": "पारंपरिक सोल्डर टिन + सीसा है, जिसका गलनांक कम होता है; तांबा + जस्ता पीतल है।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Aqua regia, which can dissolve gold, is a mixture of concentrated nitric acid and hydrochloric acid in the ratio:", "o": ["3 : 1", "1 : 3", "1 : 1", "2 : 1"], "a": 1, "e": "Aqua regia = 1 part conc. HNO₃ + 3 parts conc. HCl.", "qh": "सोने को घोल सकने वाला अम्लराज (एक्वा रेजिया) सांद्र नाइट्रिक अम्ल और हाइड्रोक्लोरिक अम्ल का किस अनुपात में मिश्रण है?", "oh": ["3 : 1", "1 : 3", "1 : 1", "2 : 1"], "eh": "अम्लराज = 1 भाग सांद्र HNO₃ + 3 भाग सांद्र HCl।", "level": "tough"}, {"s": "General Science", "t": "Chemistry", "q": "Temporary hardness of water is caused by bicarbonates of:", "o": ["Sodium and potassium", "Iron and copper", "Zinc and lead", "Calcium and magnesium"], "a": 3, "e": "Calcium and magnesium bicarbonates cause temporary hardness, removed by boiling.", "qh": "पानी की अस्थायी कठोरता किनके बाइकार्बोनेट से होती है?", "oh": ["सोडियम और पोटैशियम", "लोहा और तांबा", "जस्ता और सीसा", "कैल्शियम और मैग्नीशियम"], "eh": "कैल्शियम और मैग्नीशियम के बाइकार्बोनेट से अस्थायी कठोरता होती है, जो उबालने से दूर हो जाती है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "The absorption of digested food mainly takes place in the:", "o": ["Stomach", "Large intestine", "Small intestine", "Oesophagus"], "a": 2, "e": "Finger-like villi in the small intestine give a large surface for absorbing digested food.", "qh": "पचे हुए भोजन का अवशोषण मुख्य रूप से कहाँ होता है?", "oh": ["आमाशय", "बड़ी आँत", "छोटी आँत", "ग्रासनली"], "eh": "छोटी आँत की उंगली जैसी विलाई पचा हुआ भोजन सोखने के लिए बड़ी सतह देती हैं।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "A passenger standing in a bus falls backward when the bus suddenly starts. This is due to:", "o": ["Inertia of motion", "Inertia of rest", "Centripetal force", "Friction"], "a": 1, "e": "The lower body moves with the bus but the upper body tends to stay at rest (inertia of rest), so the passenger falls backward.", "qh": "बस अचानक चलने पर खड़ा यात्री पीछे की ओर गिरता है। इसका कारण है:", "oh": ["गति का जड़त्व", "विराम का जड़त्व", "अभिकेंद्र बल", "घर्षण"], "eh": "शरीर का निचला हिस्सा बस के साथ चल पड़ता है पर ऊपरी हिस्सा विराम में रहना चाहता है (विराम का जड़त्व), इसलिए यात्री पीछे गिरता है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "The number of chromosomes in a normal human body cell is:", "o": ["23", "46", "44", "48"], "a": 1, "e": "Human somatic cells have 46 chromosomes (23 pairs); gametes have 23.", "qh": "सामान्य मानव शरीर की कोशिका में गुणसूत्रों की संख्या कितनी होती है?", "oh": ["23", "46", "44", "48"], "eh": "मानव शरीर की कोशिकाओं में 46 गुणसूत्र (23 जोड़े) होते हैं; युग्मकों में 23।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "Which device is used to increase or decrease AC voltage?", "o": ["Transformer", "Rectifier", "Galvanometer", "Ammeter"], "a": 0, "e": "A transformer works on electromagnetic induction and changes AC voltage; it does not work with steady DC.", "qh": "AC वोल्टेज बढ़ाने या घटाने के लिए कौन-सा उपकरण इस्तेमाल होता है?", "oh": ["ट्रांसफ़ॉर्मर", "रेक्टिफ़ायर", "गैल्वेनोमीटर", "अमीटर"], "eh": "ट्रांसफ़ॉर्मर विद्युत-चुंबकीय प्रेरण पर काम करता है और AC वोल्टेज बदलता है; यह स्थिर DC पर काम नहीं करता।", "level": "easy"}, {"s": "General Science", "t": "Biology", "q": "Which plant hormone helps in the ripening of fruits?", "o": ["Ethylene", "Auxin", "Gibberellin", "Cytokinin"], "a": 0, "e": "Ethylene, a gas, speeds up fruit ripening; auxin promotes cell elongation.", "qh": "फलों को पकाने में कौन-सा पादप हॉर्मोन मदद करता है?", "oh": ["एथिलीन", "ऑक्सिन", "जिबरेलिन", "साइटोकाइनिन"], "eh": "एथिलीन गैस फलों को जल्दी पकाती है; ऑक्सिन कोशिकाओं को लंबा करता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "At what temperature do the Celsius and Fahrenheit scales show the same reading?", "o": ["0°", "−32°", "−40°", "100°"], "a": 2, "e": "F = 9C/5 + 32; putting F = C gives C = −40, so −40 °C = −40 °F.", "qh": "सेल्सियस और फ़ारेनहाइट पैमाने किस तापमान पर एक जैसी रीडिंग दिखाते हैं?", "oh": ["0°", "−32°", "−40°", "100°"], "eh": "F = 9C/5 + 32; F = C रखने पर C = −40 आता है, इसलिए −40 °C = −40 °F।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "A safety fuse in a household circuit works on which effect of electric current?", "o": ["Magnetic effect", "Heating effect", "Chemical effect", "Lighting effect"], "a": 1, "e": "Excess current heats the low-melting fuse wire, which melts and breaks the circuit.", "qh": "घरेलू सर्किट में सुरक्षा फ़्यूज़ विद्युत धारा के किस प्रभाव पर काम करता है?", "oh": ["चुंबकीय प्रभाव", "ऊष्मीय प्रभाव", "रासायनिक प्रभाव", "प्रकाश प्रभाव"], "eh": "ज़्यादा धारा कम गलनांक वाले फ़्यूज़ तार को गर्म करती है, तार पिघल जाता है और सर्किट टूट जाता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "The weight of an object on the Moon is about what fraction of its weight on Earth?", "o": ["One-half", "One-fourth", "Same as on Earth", "One-sixth"], "a": 3, "e": "The Moon's gravity is about 1/6 of Earth's, so weight is about one-sixth; mass stays the same.", "qh": "चंद्रमा पर किसी वस्तु का भार पृथ्वी के भार का लगभग कितना होता है?", "oh": ["आधा", "चौथाई", "पृथ्वी जितना ही", "छठा भाग"], "eh": "चंद्रमा का गुरुत्व पृथ्वी का लगभग 1/6 है, इसलिए भार छठा भाग रह जाता है; द्रव्यमान वही रहता है।", "level": "tough"}, {"s": "General Science", "t": "Physics", "q": "The SI unit of pressure is:", "o": ["Newton", "Pascal", "Joule", "Watt"], "a": 1, "e": "1 pascal = 1 newton per square metre.", "qh": "दाब का SI मात्रक क्या है?", "oh": ["न्यूटन", "पास्कल", "जूल", "वाट"], "eh": "1 पास्कल = 1 न्यूटन प्रति वर्ग मीटर।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "Food cooks faster in a pressure cooker because:", "o": ["Lower pressure lowers the boiling point", "Higher pressure raises the boiling point of water", "Steam is colder than water", "Heat escapes faster"], "a": 1, "e": "Inside the sealed cooker the pressure rises, so water boils at about 120 °C instead of 100 °C.", "qh": "प्रेशर कुकर में खाना जल्दी पकता है, क्योंकि:", "oh": ["कम दाब से क्वथनांक घट जाता है", "ज़्यादा दाब से पानी का क्वथनांक बढ़ जाता है", "भाप पानी से ठंडी होती है", "गर्मी जल्दी बाहर निकलती है"], "eh": "बंद कुकर के अंदर दाब बढ़ता है, इसलिए पानी 100 °C की जगह लगभग 120 °C पर उबलता है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Which organism is called the 'farmer's friend' because it improves soil?", "o": ["Earthworm", "Locust", "Rat", "Grasshopper"], "a": 0, "e": "Earthworms loosen and aerate soil and add nutrient-rich castings.", "qh": "मिट्टी सुधारने के कारण किस जीव को 'किसान का मित्र' कहा जाता है?", "oh": ["केंचुआ", "टिड्डी", "चूहा", "टिड्डा"], "eh": "केंचुए मिट्टी को भुरभुरा और हवादार बनाते हैं और पोषक मल (वर्मीकास्ट) मिलाते हैं।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which process is used to harden natural rubber by heating it with sulphur?", "o": ["Galvanisation", "Calcination", "Vulcanisation", "Polymerisation"], "a": 2, "e": "Charles Goodyear's vulcanisation cross-links rubber with sulphur to make it tough and elastic (e.g. tyres).", "qh": "प्राकृतिक रबर को गंधक के साथ गर्म करके सख्त बनाने की प्रक्रिया क्या कहलाती है?", "oh": ["गैल्वनीकरण", "निस्तापन", "वल्कनीकरण", "बहुलकीकरण"], "eh": "चार्ल्स गुडइयर का वल्कनीकरण रबर को गंधक से जोड़कर मज़बूत और लचीला बनाता है (जैसे टायर)।", "level": "tough"}, {"s": "General Science", "t": "Chemistry", "q": "Which gas forms a poisonous compound with haemoglobin and reduces the blood's ability to carry oxygen?", "o": ["Carbon dioxide", "Nitrogen", "Hydrogen", "Carbon monoxide"], "a": 3, "e": "Carbon monoxide binds haemoglobin about 200 times more strongly than oxygen, forming carboxyhaemoglobin.", "qh": "कौन-सी गैस हीमोग्लोबिन से ज़हरीला यौगिक बनाकर रक्त की ऑक्सीजन ले जाने की क्षमता घटाती है?", "oh": ["कार्बन डाइऑक्साइड", "नाइट्रोजन", "हाइड्रोजन", "कार्बन मोनोऑक्साइड"], "eh": "कार्बन मोनोऑक्साइड हीमोग्लोबिन से ऑक्सीजन की तुलना में लगभग 200 गुना ज़्यादा मज़बूती से जुड़कर कार्बोक्सीहीमोग्लोबिन बनाती है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Who first observed and named the 'cell' in 1665?", "o": ["Robert Hooke", "Robert Brown", "Anton van Leeuwenhoek", "Gregor Mendel"], "a": 0, "e": "Robert Hooke saw box-like cells in a thin slice of cork; Robert Brown later discovered the nucleus (1831).", "qh": "1665 में सबसे पहले 'कोशिका' को किसने देखा और नाम दिया?", "oh": ["रॉबर्ट हुक", "रॉबर्ट ब्राउन", "एंटोन वैन ल्यूवेनहॉक", "ग्रेगर मेंडल"], "eh": "रॉबर्ट हुक ने कॉर्क के पतले टुकड़े में डिब्बे जैसी कोशिकाएँ देखीं; बाद में रॉबर्ट ब्राउन ने केंद्रक (1831) खोजा।", "level": "easy"}, {"s": "General Science", "t": "Chemistry", "q": "Which acid is present in curd?", "o": ["Citric acid", "Acetic acid", "Lactic acid", "Tartaric acid"], "a": 2, "e": "Bacteria (Lactobacillus) turn milk sugar into lactic acid, which sets curd.", "qh": "दही में कौन-सा अम्ल होता है?", "oh": ["साइट्रिक अम्ल", "एसिटिक अम्ल", "लैक्टिक अम्ल", "टार्टरिक अम्ल"], "eh": "बैक्टीरिया (लैक्टोबैसिलस) दूध की शक्कर को लैक्टिक अम्ल में बदलते हैं, जिससे दही जमता है।", "level": "easy"}, {"s": "General Science", "t": "Physics", "q": "The power of a lens is measured in:", "o": ["Watt", "Dioptre", "Lumen", "Candela"], "a": 1, "e": "Power P = 1/f (f in metres); its unit is the dioptre (D).", "qh": "लेंस की क्षमता किस मात्रक में मापी जाती है?", "oh": ["वाट", "डायॉप्टर", "ल्यूमेन", "कैंडेला"], "eh": "क्षमता P = 1/f (f मीटर में); इसका मात्रक डायॉप्टर (D) है।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Which disease is spread by the bite of the female Aedes mosquito?", "o": ["Dengue", "Malaria", "Cholera", "Tuberculosis"], "a": 0, "e": "Dengue virus spreads through the Aedes aegypti mosquito, which bites by day; malaria spreads through the female Anopheles.", "qh": "मादा एडीज़ मच्छर के काटने से कौन-सा रोग फैलता है?", "oh": ["डेंगू", "मलेरिया", "हैजा", "क्षय रोग"], "eh": "डेंगू वायरस दिन में काटने वाले एडीज़ एजिप्टी मच्छर से फैलता है; मलेरिया मादा एनोफ़िलीज़ से फैलता है।", "level": "medium"}, {"s": "General Science", "t": "Physics", "q": "A 'light-year' is a unit of:", "o": ["Time", "Speed", "Distance", "Brightness"], "a": 2, "e": "A light-year is the distance light travels in one year, about 9.46 × 10¹² km.", "qh": "'प्रकाश-वर्ष' किसका मात्रक है?", "oh": ["समय", "चाल", "दूरी", "चमक"], "eh": "प्रकाश-वर्ष वह दूरी है जो प्रकाश एक साल में तय करता है, लगभग 9.46 × 10¹² km।", "level": "medium"}, {"s": "General Science", "t": "Biology", "q": "Tiny pores on the surface of leaves through which gases are exchanged are called:", "o": ["Lenticels", "Root hairs", "Stomata", "Chloroplasts"], "a": 2, "e": "Stomata, each surrounded by two guard cells, let in CO₂ and release O₂ and water vapour (transpiration).", "qh": "पत्तियों की सतह के वे छोटे छिद्र जिनसे गैसों का आदान-प्रदान होता है, क्या कहलाते हैं?", "oh": ["वातरंध्र (लेंटिसेल)", "मूल रोम", "रंध्र (स्टोमेटा)", "हरितलवक"], "eh": "हर रंध्र दो द्वार कोशिकाओं से घिरा होता है; इनसे CO₂ अंदर आती है और O₂ व जलवाष्प (वाष्पोत्सर्जन) बाहर जाते हैं।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "The main component of CNG (Compressed Natural Gas) is:", "o": ["Methane", "Butane", "Propane", "Ethane"], "a": 0, "e": "CNG is mostly methane (CH₄); LPG is mainly butane and propane.", "qh": "CNG (संपीडित प्राकृतिक गैस) का मुख्य घटक क्या है?", "oh": ["मीथेन", "ब्यूटेन", "प्रोपेन", "एथेन"], "eh": "CNG में ज़्यादातर मीथेन (CH₄) होती है; LPG में मुख्य रूप से ब्यूटेन और प्रोपेन होते हैं।", "level": "medium"}, {"s": "General Science", "t": "Chemistry", "q": "Atoms of the same element with the same atomic number but different mass numbers are called:", "o": ["Isobars", "Isotopes", "Isomers", "Allotropes"], "a": 1, "e": "Isotopes have the same number of protons but different numbers of neutrons, e.g. carbon-12 and carbon-14.", "qh": "एक ही तत्व के वे परमाणु जिनकी परमाणु संख्या समान हो पर द्रव्यमान संख्या अलग, क्या कहलाते हैं?", "oh": ["समभारिक (आइसोबार)", "समस्थानिक (आइसोटोप)", "समावयवी (आइसोमर)", "अपररूप (एलोट्रोप)"], "eh": "समस्थानिकों में प्रोटॉन बराबर पर न्यूट्रॉन अलग होते हैं, जैसे कार्बन-12 और कार्बन-14।", "level": "medium"}, {"s": "Mathematics", "t": "Trigonometry", "q": "If sin θ = 7/25, what is the value of cos²θ − sin²θ? (θ is acute)", "o": ["576/625", "17/25", "527/625", "336/625"], "a": 2, "e": "cos θ = 24/25. cos²θ − sin²θ = (576 − 49)/625 = 527/625.", "qh": "अगर sin θ = 7/25 है, तो cos²θ − sin²θ का मान क्या है? (θ न्यून कोण है)", "oh": ["576/625", "17/25", "527/625", "336/625"], "eh": "cos θ = 24/25. cos²θ − sin²θ = (576 − 49)/625 = 527/625।", "level": "tough"}, {"s": "Mathematics", "t": "Ages", "q": "The present ages of Pooja and Rekha are in the ratio 5 : 7. After 4 years, the ratio will be 49 : 67. What is Rekha's present age?", "o": ["63 years", "67 years", "104 years", "59 years"], "a": 0, "e": "(5x + 4)/(7x + 4) = 49/67 → x = 9; age = 7 × 9 = 63 years.", "qh": "पूजा और रेखा की अभी की आयु का अनुपात 5 : 7 है। 4 साल बाद यह अनुपात 49 : 67 हो जाएगा। रेखा की अभी की आयु कितनी है?", "oh": ["63 साल", "67 साल", "104 साल", "59 साल"], "eh": "(5x + 4)/(7x + 4) = 49/67 → x = 9; आयु = 7 × 9 = 63 साल।", "level": "tough"}, {"s": "Mathematics", "t": "Percentage", "q": "A number is increased by 50%, then decreased by 10%. The result is 21600. What was the original number?", "o": ["12960", "16000", "21600", "15200"], "a": 1, "e": "Original × 1.35 = 21600 → original = 21600 ÷ 1.35 = 16000.", "qh": "एक संख्या को पहले 50% बढ़ाया, फिर 10% घटाया। नतीजा 21600 आया। मूल संख्या क्या थी?", "oh": ["12960", "16000", "21600", "15200"], "eh": "मूल संख्या × 1.35 = 21600 → मूल संख्या = 21600 ÷ 1.35 = 16000।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 7 consecutive odd numbers is 61. What is the largest of them?", "o": ["68", "55", "67", "69"], "a": 2, "e": "The average is the middle number 61; there are 3 numbers on each side with gap 2 → largest = 67.", "qh": "7 लगातार विषम संख्याओं का औसत 61 है। उनमें सबसे बड़ी संख्या कौन-सी है?", "oh": ["68", "55", "67", "69"], "eh": "औसत ही बीच वाली संख्या 61 है; दोनों ओर 3 संख्याएँ, अंतर 2 → उत्तर = 67।", "level": "medium"}, {"s": "Mathematics", "t": "Geometry", "q": "What is each interior angle of a regular polygon with 6 sides?", "o": ["108°", "130°", "60°", "120°"], "a": 3, "e": "Interior angle = 180° − 360°/6 = 120°.", "qh": "6 भुजाओं वाले सम बहुभुज का हर अंदरूनी कोण कितना होता है?", "oh": ["108°", "130°", "60°", "120°"], "eh": "अंदरूनी कोण = 180° − 360°/6 = 120°।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "₹11,250 is divided among Rekha, Meena and Rohit in the ratio 2 : 5 : 8. What is Rohit's share?", "o": ["₹3,750", "₹1,500", "₹6,750", "₹6,000"], "a": 3, "e": "Total parts = 15; one part = ₹11,250/15 = ₹750; share = 8 × ₹750 = ₹6,000.", "qh": "₹11,250 को रेखा, मीना और रोहित में 2 : 5 : 8 के अनुपात में बाँटा गया। रोहित का हिस्सा कितना है?", "oh": ["₹3,750", "₹1,500", "₹6,750", "₹6,000"], "eh": "कुल भाग = 15; एक भाग = ₹11,250/15 = ₹750; हिस्सा = 8 × ₹750 = ₹6,000।", "level": "easy"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 50 numbers was found to be 33. Later it was discovered that 88 had been wrongly copied as 93. What is the correct average?", "o": ["33.9", "32.9", "32.4", "33.1"], "a": 1, "e": "Correct total = 50×33 − 93 + 88 = 1645; average = 32.9.", "qh": "50 संख्याओं का औसत 33 निकाला गया। बाद में पता चला कि 88 को गलती से 93 लिख लिया गया था। सही औसत क्या है?", "oh": ["33.9", "32.9", "32.4", "33.1"], "eh": "सही योग = 50×33 − 93 + 88 = 1645; औसत = 32.9।", "level": "easy"}, {"s": "Mathematics", "t": "Percentage", "q": "Only two candidates contested a panchayat election. One received 55% of the valid votes and defeated the other by a margin of 3,350 votes. Find the total valid votes polled.", "o": ["67,000", "34,500", "33,500", "33,501"], "a": 2, "e": "Margin = 55% − 45% = 10% of total = 3,350 → total = 3,350 × 100/10 = 33,500.", "qh": "एक पंचायत चुनाव में केवल दो उम्मीदवार थे। एक को 55% वैध वोट मिले और उसने दूसरे को 3,350 वोटों के अंतर से हराया। कुल वैध वोट बताइए।", "oh": ["67,000", "34,500", "33,500", "33,501"], "eh": "अंतर = 55% − 45% = कुल का 10% = 3,350 → कुल = 3,350 × 100/10 = 33,500।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "Find the largest 4-digit number that leaves no remainder when divided by 10, 15 and 25.", "o": ["9900", "9600", "9890", "9750"], "a": 0, "e": "LCM(10, 15, 25) = 150. The largest 4-digit multiple of 150 is 9900.", "qh": "4 अंकों की वह सबसे बड़ी संख्या बताइए जिसे 10, 15 और 25 से भाग देने पर कोई शेष न बचे।", "oh": ["9900", "9600", "9890", "9750"], "eh": "LCM(10, 15, 25) = 150। 150 का 4 अंकों वाला सबसे बड़ी गुणज 9900 है।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "Vikas starts a business with ₹30,000. After 8 months, Karan joins with ₹36,000. At the end of the year the profit is ₹3,500. What is Karan's share?", "o": ["₹3,000", "₹1,000", "₹1,750", "₹2,500"], "a": 1, "e": "Capital × months = 30000×12 : 36000×4 = 5 : 2. Share = 2/7 × ₹3,500 = ₹1,000.", "qh": "विकास ₹30,000 से कारोबार शुरू करता है। 8 महीने बाद करण ₹36,000 लेकर जुड़ता है। साल के आखिर में लाभ ₹3,500 है। करण का हिस्सा कितना है?", "oh": ["₹3,000", "₹1,000", "₹1,750", "₹2,500"], "eh": "पूँजी × महीने = 30000×12 : 36000×4 = 5 : 2। हिस्सा = 2/7 × ₹3,500 = ₹1,000।", "level": "easy"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "The monthly salaries of Priya and Rohit are in the ratio 4 : 5. If each gets a raise of ₹3,000, the ratio becomes 5 : 6. What is Priya's present salary?", "o": ["₹12,000", "₹24,000", "₹15,000", "₹9,000"], "a": 0, "e": "(4x + 3000)/(5x + 3000) = 5/6 → 24x − 25x = 15000 − 18000 → x = 3000; salary = 4 × 3000 = ₹12,000.", "qh": "प्रिया और रोहित के मासिक वेतन का अनुपात 4 : 5 है। अगर दोनों का वेतन ₹3,000 बढ़े, तो अनुपात 5 : 6 हो जाता है। प्रिया का वर्तमान वेतन क्या है?", "oh": ["₹12,000", "₹24,000", "₹15,000", "₹9,000"], "eh": "(4x + 3000)/(5x + 3000) = 5/6 → 24x − 25x = 15000 − 18000 → x = 3000; वेतन = 4 × 3000 = ₹12,000।", "level": "easy"}, {"s": "Mathematics", "t": "Time and Work", "q": "Manoj and Naveen can finish a work in 12 days and 24 days respectively. They work together for 5 days and then Manoj leaves. In how many days in total will the work be finished?", "o": ["14 days", "13 days", "15 days", "8 days"], "a": 0, "e": "In 5 days: 5 × (1/12 + 1/24) = 5/8 done. Left 3/8 is done by Naveen in 9 days. Total = 14 days.", "qh": "मनोज और नवीन एक काम क्रमशः 12 दिन और 24 दिन में पूरा कर सकते हैं। दोनों 5 दिन साथ काम करते हैं और फिर मनोज काम छोड़ देता है। काम कुल कितने दिन में पूरा होगा?", "oh": ["14 दिन", "13 दिन", "15 दिन", "8 दिन"], "eh": "5 दिन में: 5 × (1/12 + 1/24) = 5/8 काम हुआ। बचा 3/8 काम अकेले नवीन से 9 दिन में होता है। कुल = 14 दिन।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "Find the total number of positive divisors of 420.", "o": ["28", "8", "26", "24"], "a": 3, "e": "420 = 2^2 × 3 × 5 × 7; number of factors = (2+1) × (1+1) × (1+1) × (1+1) = 24.", "qh": "420 के कुल धनात्मक भाजकों की संख्या बताइए।", "oh": ["28", "8", "26", "24"], "eh": "420 = 2^2 × 3 × 5 × 7; गुणनखंडों की संख्या = (2+1) × (1+1) × (1+1) × (1+1) = 24।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A train 150 m long running at 45 km/h crosses a platform 450 m long. How many seconds does it take?", "o": ["96 seconds", "48 seconds", "53 seconds", "36 seconds"], "a": 1, "e": "Distance = 150 + 450 = 600 m; speed = 12.5 m/s; time = 600/12.5 = 48 s.", "qh": "150 m लंबी ट्रेन 45 km/h की रफ़्तार से 450 m लंबा प्लेटफ़ॉर्म पार करती है। इसमें कितने सेकंड लगते हैं?", "oh": ["96 सेकंड", "48 सेकंड", "53 सेकंड", "36 सेकंड"], "eh": "दूरी = 150 + 450 = 600 m; रफ़्तार = 12.5 m/s; समय = 600/12.5 = 48 सेकंड।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "Find the total surface area of a cylinder with base radius 3.5 cm and height 15 cm. (Take π = 22/7)", "o": ["814 cm²", "203.5 cm²", "451 cm²", "407 cm²"], "a": 3, "e": "TSA = 2πr(r + h) = 2 × 22/7 × 3.5 × 18.5 = 407 cm².", "qh": "3.5 cm आधार त्रिज्या और 15 cm ऊँचाई वाले बेलन का संपूर्ण पृष्ठीय क्षेत्रफल बताइए। (π = 22/7 लें)", "oh": ["814 cm²", "203.5 cm²", "451 cm²", "407 cm²"], "eh": "संपूर्ण पृष्ठीय क्षेत्रफल = 2πr(r + h) = 2 × 22/7 × 3.5 × 18.5 = 407 cm²।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The cost of 5 pens and 6 notebooks is ₹207, and the cost of 4 pens and 5 notebooks is ₹170. What is the cost of one notebook?", "o": ["₹37", "₹24", "₹15", "₹22"], "a": 3, "e": "5p + 6n = 207, 4p + 5n = 170. Eliminating p: n = (5×170 − 4×207)/(5×5 − 4×6) = ₹22; pen = ₹15.", "qh": "5 पेन और 6 कॉपियों का दाम ₹207 है, और 4 पेन और 5 कॉपियों का दाम ₹170 है। एक कॉपी का दाम कितना है?", "oh": ["₹37", "₹24", "₹15", "₹22"], "eh": "5p + 6n = 207, 4p + 5n = 170। p हटाने पर: n = (5×170 − 4×207)/(5×5 − 4×6) = ₹22; पेन = ₹15।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "At what rate of simple interest per annum will a sum of money become double itself in 20 years?", "o": ["10%", "5%", "2.5%", "7%"], "a": 1, "e": "Interest = 1 × P = P × R × 20/100 → R = 100/20 = 5%.", "qh": "साधारण ब्याज की किस वार्षिक दर से कोई धनराशि 20 साल में दोगुनी हो जाएगी?", "oh": ["10%", "5%", "2.5%", "7%"], "eh": "ब्याज = 1 × P = P × R × 20/100 → R = 100/20 = 5%।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "Pipes A and B can fill a tank in 18 hours and 36 hours, while pipe C can empty the full tank in 36 hours. If all three are opened together on an empty tank, in how many hours will it be full?", "o": ["17 hours", "27 hours", "18 hours", "14 hours"], "a": 2, "e": "Net per hour = 1/18 + 1/36 − 1/36 = 1/18 → 18 hours.", "qh": "पाइप A और B एक टंकी को 18 घंटे और 36 घंटे में भरते हैं, जबकि पाइप C भरी टंकी को 36 घंटे में खाली करता है। खाली टंकी पर तीनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["17 घंटे", "27 घंटे", "18 घंटे", "14 घंटे"], "eh": "हर घंटे कुल भराई = 1/18 + 1/36 − 1/36 = 1/18 → 18 घंटे।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A seller suffers a loss of 5% when he sells a sewing machine for ₹760. What should the selling price be to make a profit of 15%?", "o": ["₹970", "₹912", "₹800", "₹920"], "a": 3, "e": "CP = ₹760 × 100/95 = ₹800; required SP = ₹800 × 115/100 = ₹920.", "qh": "एक सिलाई मशीन ₹760 में बेचने पर विक्रेता को 5% हानि होती है। 15% लाभ कमाने के लिए विक्रय मूल्य क्या होना चाहिए?", "oh": ["₹970", "₹912", "₹800", "₹920"], "eh": "क्रय मूल्य = ₹760 × 100/95 = ₹800; ज़रूरी विक्रय मूल्य = ₹800 × 115/100 = ₹920।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "After a 8% loss, the selling price of a mixer-grinder is ₹2,944. Find the price at which it was bought.", "o": ["₹3,250", "₹3,160", "₹3,201", "₹3,200"], "a": 3, "e": "CP = SP × 100/92 = ₹2,944 × 100/92 = ₹3,200.", "qh": "8% हानि के बाद एक मिक्सर-ग्राइंडर का विक्रय मूल्य ₹2,944 है। इसे किस दाम पर खरीदा गया था?", "oh": ["₹3,250", "₹3,160", "₹3,201", "₹3,200"], "eh": "क्रय मूल्य = विक्रय मूल्य × 100/92 = ₹2,944 × 100/92 = ₹3,200।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Two trains 160 m and 140 m long are running on parallel tracks in the same direction at 72 km/h and 36 km/h. How long will the faster train take to completely pass the slower one?", "o": ["10 seconds", "30 seconds", "34 seconds", "27 seconds"], "a": 1, "e": "Relative speed = 72 − 36 = 36 km/h = 10 m/s; distance = 160 + 140 = 300 m; time = 30 s.", "qh": "160 m और 140 m लंबी दो रेलगाड़ियाँ समांतर पटरियों पर एक ही दिशा में 72 km/h और 36 km/h की चाल से चल रही हैं। तेज़ गाड़ी धीमी गाड़ी को पूरी तरह पार करने में कितना समय लेगी?", "oh": ["10 सेकंड", "30 सेकंड", "34 सेकंड", "27 सेकंड"], "eh": "सापेक्ष चाल = 72 − 36 = 36 km/h = 10 m/s; दूरी = 160 + 140 = 300 m; समय = 30 सेकंड।", "level": "medium"}, {"s": "Mathematics", "t": "Mensuration", "q": "What is the curved surface area of a cone with radius 14 cm and height 48 cm? (Take π = 22/7)", "o": ["2200 cm²", "4400 cm²", "3300 cm²", "2156 cm²"], "a": 0, "e": "slant height l = √(14² + 48²) = 50; πrl = 22/7 × 14 × 50 = 2200 cm².", "qh": "14 cm त्रिज्या और ऊँचाई 48 cm वाले शंकु का वक्र पृष्ठीय क्षेत्रफल कितना है? (π = 22/7 लें)", "oh": ["2200 cm²", "4400 cm²", "3300 cm²", "2156 cm²"], "eh": "तिरछी ऊँचाई l = √(14² + 48²) = 50; πrl = 22/7 × 14 × 50 = 2200 cm²।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Karan bought a used motorcycle for ₹9,000 and spent ₹2,300 on servicing. He sold it for ₹14,125. What is his profit percentage?", "o": ["25%", "30%", "37.5%", "56 17/18%"], "a": 0, "e": "Total CP = ₹9,000 + ₹2,300 = ₹11,300; profit = ₹2,825; profit % = ₹2,825/₹11,300 × 100 = 25%.", "qh": "करण ने एक पुरानी मोटरसाइकिल ₹9,000 में खरीदा और ₹2,300 सर्विसिंग पर खर्च किए। उसने इसे ₹14,125 में बेचा। उसका लाभ प्रतिशत क्या है?", "oh": ["25%", "30%", "37.5%", "56 17/18%"], "eh": "कुल क्रय मूल्य = ₹9,000 + ₹2,300 = ₹11,300; लाभ = ₹2,825; लाभ % = ₹2,825/₹11,300 × 100 = 25%।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 2 1/8 + 3 5/8 − 2 1/3", "o": ["41/6", "41/12", "47/12", "37/12"], "a": 1, "e": "Convert to improper fractions: 17/8, 29/8, 7/3. Working step by step gives 41/12.", "qh": "सरल कीजिए: 2 1/8 + 3 5/8 − 2 1/3", "oh": ["41/6", "41/12", "47/12", "37/12"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 17/8, 29/8, 7/3। क्रम से हल करने पर 41/12।", "level": "easy"}, {"s": "Mathematics", "t": "Simplification", "q": "What is the value of √5329 + ∛2197?", "o": ["172", "96", "86", "84"], "a": 2, "e": "√5329 = 73, ∛2197 = 13; sum = 86.", "qh": "√5329 + ∛2197 का मान क्या है?", "oh": ["172", "96", "86", "84"], "eh": "√5329 = 73, ∛2197 = 13; योग = 86।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nD5Z, H10W, L15T, P20Q, ?", "o": ["T25N", "T24N", "U25N", "T25O"], "a": 0, "e": "First letter +4; number: add 5; last letter -3. So ? = T25N.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nD5Z, H10W, L15T, P20Q, ?", "oh": ["T25N", "T24N", "U25N", "T25O"], "eh": "पहला अक्षर +4; संख्या: 5 जोड़ें; आखिरी अक्षर -3। इसलिए ? = T25N।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Amit starts from point P, walks 10 km towards North, then turns right and walks 12 km, then turns right and walks 5 km. How far is Amit from point P now?", "o": ["13 km", "12 km", "15 km", "27 km"], "a": 0, "e": "Net East–West = +12 km, net North–South = +5 km; distance = √(12² + 5²) = 13 km.", "qh": "अमित बिंदु P से शुरू करके उत्तर की ओर 10 km चलता है, फिर दाएँ मुड़कर 12 km चलता है, फिर दाएँ मुड़कर 5 km चलता है। अब अमित बिंदु P से कितनी दूर है?", "oh": ["13 km", "12 km", "15 km", "27 km"], "eh": "कुल पूर्व–पश्चिम = +12 km, कुल उत्तर–दक्षिण = +5 km; दूरी = √(12² + 5²) = 13 km।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nDoctor : Hospital :: Teacher : ?", "o": ["Student", "Book", "Class", "School"], "a": 3, "e": "Relation: 'works in'. Doctor – Hospital, so Teacher – School.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nडॉक्टर : अस्पताल :: शिक्षक : ?", "oh": ["छात्र", "किताब", "कक्षा", "स्कूल"], "eh": "संबंध: 'में काम करता है'। डॉक्टर – अस्पताल, इसलिए शिक्षक – स्कूल।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n% 7 $ D € 4 & £ % Q M 5 € D 7 9 I 6 © R * 3\nHow many odd numbers are there in the arrangement, each of which is immediately preceded by a symbol?", "o": ["5", "1", "4", "2"], "a": 3, "e": "Matching places: %7$, *3 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n% 7 $ D € 4 & £ % Q M 5 € D 7 9 I 6 © R * 3\nइस क्रम में ऐसी कितनी विषम संख्याएँ हैं, जिनके ठीक पहले एक चिह्न है?", "oh": ["5", "1", "4", "2"], "eh": "शर्त पूरी करने वाले स्थान: %7$, *3 → 2।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["EGKM", "MOSU", "BDGI", "JLPR"], "a": 2, "e": "In EGKM, MOSU, JLPR the gaps are +2, +4, +2; in BDGI they are +2, +3, +2.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["EGKM", "MOSU", "BDGI", "JLPR"], "eh": "EGKM, MOSU, JLPR में अंतर +2, +4, +2 है; BDGI में +2, +3, +2 है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'GLASS' is written as 'INCUU'. How will 'HORSE' be written in that language?", "o": ["GUTQJ", "KRUVH", "JQTUG", "JQTUF"], "a": 2, "e": "Rule: each letter moves +2. Applying it to HORSE gives JQTUG.", "qh": "एक कोड भाषा में 'GLASS' को 'INCUU' लिखा जाता है। उसी भाषा में 'HORSE' को कैसे लिखा जाएगा?", "oh": ["GUTQJ", "KRUVH", "JQTUG", "JQTUF"], "eh": "नियम: हर अक्षर +2 खिसकता है। HORSE पर लगाने से JQTUG मिलता है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Data Sufficiency", "q": "Question: What is the present age of Naveen?\nStatement I: The sum of the ages of Naveen and Rahul is 39 years.\nStatement II: Naveen is 19 years younger than Rahul.\nWhich of the following is correct?", "o": ["The data in statement I alone is sufficient", "The data in statement II alone is sufficient", "The data in either statement I alone or statement II alone is sufficient", "The data in both statements I and II together is needed"], "a": 3, "e": "Neither alone is enough, but together they give one value.", "qh": "प्रश्न: नवीन की अभी की आयु क्या है?\nकथन I: नवीन और राहुल की आयु का योग 39 साल है।\nकथन II: नवीन, राहुल से 19 साल छोटा है।\nनीचे दिए विकल्पों में से कौन-सा सही है?", "oh": ["केवल कथन I का आँकड़ा काफ़ी है", "केवल कथन II का आँकड़ा काफ़ी है", "अकेले कथन I या अकेले कथन II, कोई भी काफ़ी है", "दोनों कथन I और II साथ में चाहिए"], "eh": "अकेले कोई काफ़ी नहीं, पर दोनों मिलकर एक ही मान देते हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo rivers are books.\nAll books are boats.\nConclusions:\nI. Some boats are books.\nII. Some books are rivers.", "o": ["Both I and II follow", "Only conclusion II follows", "Only conclusion I follows", "Neither I nor II follows"], "a": 2, "e": "Conclusion I is true in every possible diagram; II is not.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी नदियाँ किताबें नहीं है।\nसभी किताबें नावें हैं।\nनिष्कर्ष:\nI. कुछ नावें किताबें हैं।\nII. कुछ किताबें नदियाँ हैं।", "oh": ["I और II दोनों सही हैं", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है", "न I सही है, न II"], "eh": "निष्कर्ष I हर संभव आरेख में सही है; II नहीं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "R, A, U, H, V and W are sitting in a row, all facing North.\nExactly 4 persons sit between W and H.\nExactly 1 person sits between H and A.\nV sits second to the right of U.\nU and H sit next to each other.\nR and W sit next to each other.\nA does not sit at either end.\nW is not an immediate neighbour of A.\nHow many persons sit between U and W?", "o": ["5", "6", "3", "2"], "a": 2, "e": "Only one order fits all clues (left to right): H U A V R W. Answer: 3.", "qh": "R, A, U, H, V और W एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nW और H के बीच ठीक 4 व्यक्ति बैठे हैं।\nH और A के बीच ठीक 1 व्यक्ति बैठे हैं।\nV, U के दाईं ओर दूसरे स्थान पर बैठा है।\nU और H पास-पास बैठे हैं।\nR और W पास-पास बैठे हैं।\nA किसी भी छोर पर नहीं बैठा है।\nW, A का ठीक पड़ोसी नहीं है।\nU और W के बीच कितने व्यक्ति बैठे हैं?", "oh": ["5", "6", "3", "2"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): H U A V R W। उत्तर: 3।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'new book very' is written as 'ki xi pu',\n'water new green' is written as 'lo pu ni',\n'book big water' is written as 'ki lo ra',\nWhat is the code for 'water'?", "o": ["pu", "lo", "ki", "xi"], "a": 1, "e": "Compare the sentences: common words and common codes match. This gives 'water' = 'lo'.", "qh": "एक कोड भाषा में:\n'new book very' को 'ki xi pu' लिखा जाता है,\n'water new green' को 'lo pu ni' लिखा जाता है,\n'book big water' को 'ki lo ra' लिखा जाता है,\n'water' का कोड क्या है?", "oh": ["pu", "lo", "ki", "xi"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'water' = 'lo' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nMVKA : KTLD :: TRBL : ?", "o": ["OCPR", "RPCO", "VTAI", "RPCP"], "a": 1, "e": "Each letter moves -2, -2, +1, +3 in order. TRBL → RPCO.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nMVKA : KTLD :: TRBL : ?", "oh": ["OCPR", "RPCO", "VTAI", "RPCP"], "eh": "हर अक्षर क्रम से -2, -2, +1, +3 खिसकता है। TRBL → RPCO।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Statement and Conclusion", "q": "Read the statement and the conclusions/assumptions given below and decide which of them logically follow(s).\nStatement: 'Carry an umbrella; it may rain this evening,' a mother tells her son.\nAssumptions:\nI. An umbrella protects from rain.\nII. It always rains in the evening.", "o": ["Only conclusion II follows", "Both I and II follow", "Neither I nor II follows", "Only conclusion I follows"], "a": 3, "e": "The advice makes sense only if an umbrella protects from rain (I). 'May rain' shows it does not always rain (II is not assumed).", "qh": "नीचे दिए कथन और निष्कर्ष/धारणाएँ पढ़कर तय कीजिए कि कौन-सा/से तर्क के आधार पर सही है/हैं।\nकथन: एक माँ बेटे से कहती है, 'छाता ले जाओ, आज शाम बारिश हो सकती है।'\nधारणाएँ:\nI. छाता बारिश से बचाता है।\nII. शाम को हमेशा बारिश होती है।", "oh": ["केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II", "केवल निष्कर्ष I सही है"], "eh": "सलाह तभी ठीक है जब छाता बारिश से बचाए (I)। 'हो सकती है' से साफ़ है कि हमेशा बारिश नहीं होती (II नहीं)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n5 9 8 8 2 6 9 1 2 1 7 7 3 5 4 7 8 1 6 4 4 8 1 4 3\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["2", "1", "3", "4"], "a": 1, "e": "Matching groups: 3 5 4 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n5 9 8 8 2 6 9 1 2 1 7 7 3 5 4 7 8 1 6 4 4 8 1 4 3\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["2", "1", "3", "4"], "eh": "शर्त पूरी करने वाले समूह: 3 5 4 → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nTKBQ : VMDU :: SZOE : ?", "o": ["IQBU", "QXMA", "UBQJ", "UBQI"], "a": 3, "e": "Each letter moves +2, +2, +2, +4 in order. SZOE → UBQI.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nTKBQ : VMDU :: SZOE : ?", "oh": ["IQBU", "QXMA", "UBQJ", "UBQI"], "eh": "हर अक्षर क्रम से +2, +2, +2, +4 खिसकता है। SZOE → UBQI।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "Q, L, J, V, K, R, E and C are sitting around a circular table, all facing the centre.\nQ sits immediately to the left of C.\nJ sits immediately to the right of K.\nR sits second to the left of V.\nE sits opposite Q.\nL is an immediate neighbour of V.\nR is an immediate neighbour of L.\nL sits second to the left of Q.\nWho sits to the immediate right of K?", "o": ["J", "E", "C", "R"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from K: K → J → E → R → L → V → Q → C. Answer: J.", "qh": "Q, L, J, V, K, R, E और C एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nQ, C के ठीक बाईं ओर बैठा है।\nJ, K के ठीक दाईं ओर बैठा है।\nR, V के बाईं ओर दूसरे स्थान पर बैठा है।\nE, Q के ठीक सामने बैठा है।\nL, V का ठीक पड़ोसी है।\nR, L का ठीक पड़ोसी है।\nL, Q के बाईं ओर दूसरे स्थान पर बैठा है।\nK के ठीक दाईं ओर कौन बैठा है?", "oh": ["J", "E", "C", "R"], "eh": "केवल एक व्यवस्था बैठती है। K से दाईं ओर (घड़ी की उलटी दिशा में) चलें: K → J → E → R → L → V → Q → C। उत्तर: J।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n257   143   843   341   968\nIf the digits in each number are arranged in descending order within the number, what is the middle digit of the number that is third from the top when the new numbers are arranged in ascending order?", "o": ["7", "6", "4", "5"], "a": 3, "e": "New numbers: 752, 431, 843, 431, 986; ascending: 431, 431, 752, 843, 986; third = 752; middle digit = 5.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n257   143   843   341   968\nअगर हर संख्या के अंकों को उसी संख्या के अंदर घटते क्रम में लगाया जाए, और फिर नई संख्याओं को बढ़ते क्रम में लगाया जाए, तो ऊपर से तीसरी संख्या का बीच वाला अंक क्या होगा?", "oh": ["7", "6", "4", "5"], "eh": "नई संख्याएँ: 752, 431, 843, 431, 986; बढ़ता क्रम: 431, 431, 752, 843, 986; तीसरी = 752; बीच का अंक = 5।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nEJQ, FMU, GPY, HSC, ?", "o": ["IVI", "IXG", "IVG", "IUG"], "a": 2, "e": "Letter positions move by +1, +3, +4 (for 1st, 2nd, 3rd letters). So ? = IVG.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nEJQ, FMU, GPY, HSC, ?", "oh": ["IVI", "IXG", "IVG", "IUG"], "eh": "अक्षरों की स्थिति +1, +3, +4 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = IVG।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n3, 8, 15, 24, 35, ?", "o": ["48", "50", "53", "44"], "a": 0, "e": "Rule: n² − 1 for n = 2, 3, … So ? = 48.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n3, 8, 15, 24, 35, ?", "oh": ["48", "50", "53", "44"], "eh": "नियम: n² − 1, जहाँ n = 2, 3, … इसलिए ? = 48।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\nF M 5 @ 8 3 F + 7 L J # + Q 9 F M A 5 H 3 6\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["6", "4", "5", "3"], "a": 3, "e": "Matching places: FM5, MA5, 5H3 → 3.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\nF M 5 @ 8 3 F + 7 L J # + Q 9 F M A 5 H 3 6\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["6", "4", "5", "3"], "eh": "शर्त पूरी करने वाले स्थान: FM5, MA5, 5H3 → 3।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n41 : 574 :: 23 : ?", "o": ["736", "737", "759", "713"], "a": 0, "e": "Rule: x → x × (x with digits reversed). 41 → 574, so 23 → 736.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n41 : 574 :: 23 : ?", "oh": ["736", "737", "759", "713"], "eh": "नियम: x → x × (x के अंक उलटे)। 41 → 574, इसलिए 23 → 736।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nKTZ, QWB, WZD, CCF, ?", "o": ["IEH", "KFH", "IHH", "IFH"], "a": 3, "e": "Letter positions move by +6, +3, +2 (for 1st, 2nd, 3rd letters). So ? = IFH.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nKTZ, QWB, WZD, CCF, ?", "oh": ["IEH", "KFH", "IHH", "IFH"], "eh": "अक्षरों की स्थिति +6, +3, +2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = IFH।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Rohit starts from point P, walks 2 km towards South, then turns left and walks 6 km, then turns left and walks 15 km, then turns left and walks 12 km, then turns left and walks 5 km. What is the distance and direction of Rohit from point P now?", "o": ["10 km, South-East", "14 km, North-West", "10 km, North-West", "12 km, North-West"], "a": 2, "e": "Net East–West = -6 km, net North–South = +8 km; distance = √(-6² + 8²) = 10 km; direction = North-West.", "qh": "रोहित बिंदु P से शुरू करके दक्षिण की ओर 2 km चलता है, फिर बाएँ मुड़कर 6 km चलता है, फिर बाएँ मुड़कर 15 km चलता है, फिर बाएँ मुड़कर 12 km चलता है, फिर बाएँ मुड़कर 5 km चलता है। अब रोहित बिंदु P से कितनी दूरी पर और किस दिशा में है?", "oh": ["10 km, दक्षिण-पूर्व", "14 km, उत्तर-पश्चिम", "10 km, उत्तर-पश्चिम", "12 km, उत्तर-पश्चिम"], "eh": "कुल पूर्व–पश्चिम = -6 km, कुल उत्तर–दक्षिण = +8 km; दूरी = √(-6² + 8²) = 10 km; दिशा = उत्तर-पश्चिम।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '×', '−' means '÷', '×' means '+', '÷' means '−', then what is the value of the following expression?\n16 + 20 ÷ 9 ÷ 16 × 20 = ?", "o": ["312", "630", "325", "315"], "a": 3, "e": "Replace the signs: 16 × 20 − 9 − 16 + 20 = 315 (using BODMAS).", "qh": "अगर '+' का मतलब '×', '−' का मतलब '÷', '×' का मतलब '+', '÷' का मतलब '−' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n16 + 20 ÷ 9 ÷ 16 × 20 = ?", "oh": ["312", "630", "325", "315"], "eh": "चिह्न बदलें: 16 × 20 − 9 − 16 + 20 = 315 (BODMAS से)।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n+ 6 & N $ C 6 @ T N L © 2 8 F © 3 8 R 4 5 1\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["2", "1", "4", "3"], "a": 1, "e": "Matching places: 8R4 → 1.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n+ 6 & N $ C 6 @ T N L © 2 8 F © 3 8 R 4 5 1\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["2", "1", "4", "3"], "eh": "शर्त पूरी करने वाले स्थान: 8R4 → 1।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n3, 4, 10, 33, 136, ?", "o": ["684", "687", "688", "685"], "a": 3, "e": "Rule: ×1 + 1, ×2 + 2, ×3 + 3, … So ? = 685.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n3, 4, 10, 33, 136, ?", "oh": ["684", "687", "688", "685"], "eh": "नियम: ×1 + 1, ×2 + 2, ×3 + 3, … इसलिए ? = 685।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "Q is the son of K. K is the husband of U. How is Q related to U?", "o": ["Grandfather", "Son", "Son-in-law", "Father"], "a": 1, "e": "Draw the family tree: Q → K: son; K → U: husband. So Q is the son of U.", "qh": "Q, K का बेटा है। K, U का पति है। Q का U से क्या संबंध है?", "oh": ["दादा/नाना", "बेटा", "दामाद", "पिता"], "eh": "परिवार का चार्ट बनाएँ: Q → K: बेटा; K → U: पति। इसलिए Q, U का बेटा है।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "T, C, H, J and G are sitting in a row, all facing North.\nExactly 1 person sits between T and H.\nG sits immediately to the right of J.\nExactly 2 persons sit between T and J.\nT is not an immediate neighbour of G.\nC is not an immediate neighbour of J.\nWho sits exactly in the middle of the row?", "o": ["G", "J", "H", "C"], "a": 2, "e": "Only one order fits all clues (left to right): T C H J G. Answer: H.", "qh": "T, C, H, J और G एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nT और H के बीच ठीक 1 व्यक्ति बैठे हैं।\nG, J के ठीक दाईं ओर बैठा है।\nT और J के बीच ठीक 2 व्यक्ति बैठे हैं।\nT, G का ठीक पड़ोसी नहीं है।\nC, J का ठीक पड़ोसी नहीं है।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["G", "J", "H", "C"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): T C H J G। उत्तर: H।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["144", "64", "37", "121"], "a": 2, "e": "All except 37 are perfect squares.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["144", "64", "37", "121"], "eh": "37 को छोड़कर सभी पूर्ण वर्ग हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a row of students, Rohit is 19th from the left end and 25th from the right end. How many students are there in the row?", "o": ["44", "45", "41", "43"], "a": 3, "e": "Total = 19 + 25 − 1 = 43.", "qh": "छात्रों की एक पंक्ति में रोहित बाएँ छोर से 19वें और दाएँ छोर से 25वें स्थान पर है। पंक्ति में कितने छात्र हैं?", "oh": ["44", "45", "41", "43"], "eh": "कुल = 19 + 25 − 1 = 43।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "If 20 January 2028 was a Thursday, what day of the week was 10 June 2028?", "o": ["Saturday", "Sunday", "Friday", "Monday"], "a": 0, "e": "Days from 20 January 2028 to 10 June 2028 = 142. 142 = 7 × 20 + 2 → 2 odd day(s) after Thursday = Saturday.", "qh": "अगर 20 जनवरी 2028 को गुरुवार था, तो 10 जून 2028 को कौन-सा दिन था?", "oh": ["शनिवार", "रविवार", "शुक्रवार", "सोमवार"], "eh": "20 जनवरी 2028 से 10 जून 2028 तक दिन = 142। 142 = 7 × 20 + 2 → गुरुवार के 2 दिन बाद = शनिवार।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "Where is the headquarters of the South Central Railway zone?", "o": ["Hyderabad (Nampally)", "Secunderabad", "Vijayawada", "Guntakal"], "a": 1, "e": "South Central Railway (formed 1966) is headquartered at Rail Nilayam, Secunderabad.", "qh": "दक्षिण मध्य रेलवे ज़ोन का मुख्यालय कहाँ है?", "oh": ["हैदराबाद (नामपल्ली)", "सिकंदराबाद", "विजयवाड़ा", "गुंटकल"], "eh": "दक्षिण मध्य रेलवे (1966 में बना) का मुख्यालय सिकंदराबाद के रेल निलयम में है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Computer", "q": "Which keyboard shortcut saves the current file in most Windows programs?", "o": ["Ctrl + A", "Ctrl + S", "Ctrl + V", "Ctrl + N"], "a": 1, "e": "Ctrl + S saves; Ctrl + A selects all, Ctrl + V pastes and Ctrl + N opens a new file.", "qh": "ज़्यादातर विंडोज़ प्रोग्राम में मौजूदा फ़ाइल सेव करने का शॉर्टकट कौन-सा है?", "oh": ["Ctrl + A", "Ctrl + S", "Ctrl + V", "Ctrl + N"], "eh": "Ctrl + S सेव करता है; Ctrl + A सब चुनता है, Ctrl + V पेस्ट करता है और Ctrl + N नई फ़ाइल खोलता है।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who won Brazil's presidential election run-off in October 2026, securing a fourth term?", "o": ["Flávio Bolsonaro", "Jair Bolsonaro", "Luiz Inácio Lula da Silva", "Dilma Rousseff"], "a": 2, "e": "Lula won the run-off with about 51.8% of the vote against Flávio Bolsonaro.", "qh": "अक्टूबर 2026 में ब्राज़ील के राष्ट्रपति चुनाव का दूसरा दौर जीतकर चौथा कार्यकाल किसने हासिल किया?", "oh": ["फ़्लावियो बोल्सोनारो", "जायर बोल्सोनारो", "लुइज़ इनासियो लूला दा सिल्वा", "डिल्मा रूसेफ़"], "eh": "लूला ने दूसरे दौर में फ़्लावियो बोल्सोनारो के खिलाफ़ लगभग 51.8% वोट पाकर जीत हासिल की।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Who was the first President of India?", "o": ["Dr Rajendra Prasad", "Dr S. Radhakrishnan", "Zakir Husain", "V. V. Giri"], "a": 0, "e": "Dr Rajendra Prasad was President from 1950 to 1962, the only one to serve two full terms.", "qh": "भारत के पहले राष्ट्रपति कौन थे?", "oh": ["डॉ. राजेंद्र प्रसाद", "डॉ. एस. राधाकृष्णन", "ज़ाकिर हुसैन", "वी. वी. गिरि"], "eh": "डॉ. राजेंद्र प्रसाद 1950 से 1962 तक राष्ट्रपति रहे — दो पूरे कार्यकाल वाले अकेले राष्ट्रपति।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "Who built the Grand Trunk Road and introduced the silver coin 'Rupiya'?", "o": ["Akbar", "Sher Shah Suri", "Alauddin Khalji", "Muhammad bin Tughlaq"], "a": 1, "e": "Sher Shah Suri (1540–45) improved the road from Bengal to the north-west and issued the silver rupiya.", "qh": "ग्रैंड ट्रंक रोड बनवाने और चाँदी का सिक्का 'रुपया' चलाने का श्रेय किसे है?", "oh": ["अकबर", "शेरशाह सूरी", "अलाउद्दीन खिलजी", "मुहम्मद बिन तुग़लक"], "eh": "शेरशाह सूरी (1540–45) ने बंगाल से उत्तर-पश्चिम तक की सड़क सुधारी और चाँदी का रुपया चलाया।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Current Affairs", "q": "Who took over as the 31st Chief of the Army Staff of India on 30 June 2026?", "o": ["General Upendra Dwivedi", "Lt Gen Sandeep Jain", "General Manoj Pande", "General Dhiraj Seth"], "a": 3, "e": "General Dhiraj Seth of the 2nd Lancers became the 31st COAS, the first Armoured Corps officer to lead the Army in 30 years.", "qh": "30 जून 2026 को भारत के 31वें थल सेनाध्यक्ष किसने कार्यभार संभाला?", "oh": ["जनरल उपेंद्र द्विवेदी", "लेफ्टिनेंट जनरल संदीप जैन", "जनरल मनोज पांडे", "जनरल धीरज सेठ"], "eh": "2nd लांसर्स के जनरल धीरज सेठ 31वें थल सेनाध्यक्ष बने — 30 साल में सेना का नेतृत्व करने वाले पहले बख्तरबंद कोर अधिकारी।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Static GK", "q": "National Sports Day in India (29 August) is celebrated on the birth anniversary of:", "o": ["Major Dhyan Chand", "Milkha Singh", "P. T. Usha", "Sachin Tendulkar"], "a": 0, "e": "Hockey wizard Major Dhyan Chand was born on 29 August 1905.", "qh": "भारत में राष्ट्रीय खेल दिवस (29 अगस्त) किसकी जयंती पर मनाया जाता है?", "oh": ["मेजर ध्यानचंद", "मिल्खा सिंह", "पी. टी. उषा", "सचिन तेंदुलकर"], "eh": "हॉकी के जादूगर मेजर ध्यानचंद का जन्म 29 अगस्त 1905 को हुआ था।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "History", "q": "The Swaraj Party was founded in 1923 by Chittaranjan Das and:", "o": ["Jawaharlal Nehru", "Lala Lajpat Rai", "Motilal Nehru", "Bal Gangadhar Tilak"], "a": 2, "e": "C. R. Das and Motilal Nehru formed the Swaraj Party to contest council elections and oppose the government from within.", "qh": "1923 में स्वराज पार्टी की स्थापना चित्तरंजन दास और किसने की?", "oh": ["जवाहरलाल नेहरू", "लाला लाजपत राय", "मोतीलाल नेहरू", "बाल गंगाधर तिलक"], "eh": "सी. आर. दास और मोतीलाल नेहरू ने परिषद चुनाव लड़कर अंदर से सरकार का विरोध करने के लिए स्वराज पार्टी बनाई।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "The Sundarbans, famous for the Royal Bengal tiger, is the delta of which rivers?", "o": ["Godavari and Krishna", "Mahanadi and Brahmani", "Indus and Sutlej", "Ganga and Brahmaputra"], "a": 3, "e": "The Sundarbans mangroves lie in the Ganga–Brahmaputra delta in West Bengal and Bangladesh.", "qh": "रॉयल बंगाल टाइगर के लिए प्रसिद्ध सुंदरबन किन नदियों का डेल्टा है?", "oh": ["गोदावरी और कृष्णा", "महानदी और ब्राह्मणी", "सिंधु और सतलुज", "गंगा और ब्रह्मपुत्र"], "eh": "सुंदरबन के मैंग्रोव पश्चिम बंगाल और बांग्लादेश में गंगा–ब्रह्मपुत्र डेल्टा में हैं।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "Pradhan Mantri MUDRA Yojana provides loans mainly to:", "o": ["Small and micro businesses", "Large industries", "Farmers for crop insurance", "Students for higher education"], "a": 0, "e": "Launched in 2015, MUDRA gives collateral-free loans to micro and small enterprises under Shishu, Kishore, Tarun (and Tarun Plus) categories.", "qh": "प्रधानमंत्री मुद्रा योजना मुख्य रूप से किसे कर्ज़ देती है?", "oh": ["छोटे और सूक्ष्म व्यवसायों को", "बड़े उद्योगों को", "फ़सल बीमा के लिए किसानों को", "उच्च शिक्षा के लिए छात्रों को"], "eh": "2015 में शुरू मुद्रा योजना शिशु, किशोर, तरुण (और तरुण प्लस) श्रेणियों में सूक्ष्म और छोटे उद्यमों को बिना गारंटी कर्ज़ देती है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "Which film won the Palme d'Or at the Cannes Film Festival 2026?", "o": ["Anora", "Minotaur", "Amma Ariyan", "Fjord"], "a": 3, "e": "Cristian Mungiu's Norway-set drama 'Fjord' won the Palme d'Or at the 79th Cannes festival; 'Minotaur' won the Grand Prix.", "qh": "कान फ़िल्म महोत्सव 2026 में पाम डी'ओर किस फ़िल्म को मिला?", "oh": ["अनोरा", "मिनोटॉर", "अम्मा अरियान", "फ़्योर्ड"], "eh": "क्रिस्टियन मुंगिउ की नॉर्वे पर आधारित फ़िल्म 'फ़्योर्ड' को 79वें कान महोत्सव में पाम डी'ओर मिला; 'मिनोटॉर' को ग्रां प्री मिला।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Art & Culture", "q": "Chhau, a dance form that often uses masks, is performed mainly in which region?", "o": ["Odisha, Jharkhand and West Bengal", "Kerala and Tamil Nadu", "Punjab and Haryana", "Gujarat and Rajasthan"], "a": 0, "e": "Chhau has three styles — Seraikella (Jharkhand), Purulia (West Bengal) and Mayurbhanj (Odisha); it is on UNESCO's intangible heritage list.", "qh": "अक्सर मुखौटों वाला छऊ नृत्य मुख्य रूप से किस क्षेत्र में किया जाता है?", "oh": ["ओडिशा, झारखंड और पश्चिम बंगाल", "केरल और तमिलनाडु", "पंजाब और हरियाणा", "गुजरात और राजस्थान"], "eh": "छऊ की तीन शैलियाँ हैं — सरायकेला (झारखंड), पुरुलिया (पश्चिम बंगाल) और मयूरभंज (ओडिशा); यह यूनेस्को की अमूर्त विरासत सूची में है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Economy", "q": "The Green Energy Corridor Phase-III scheme approved by the Union Cabinet in September 2026 aims to evacuate up to how much renewable power?", "o": ["50 GW", "500 GW", "135 GW", "20 GW"], "a": 2, "e": "GEC-III (outlay ₹1,86,405 crore) will strengthen intra-state transmission for up to 135 GW of renewable energy and add 50 GWh of battery storage by 2032-33.", "qh": "सितंबर 2026 में केंद्रीय मंत्रिमंडल से मंज़ूर हरित ऊर्जा गलियारा चरण-III योजना कितनी नवीकरणीय बिजली की निकासी के लिए है?", "oh": ["50 GW", "500 GW", "135 GW", "20 GW"], "eh": "GEC-III (खर्च ₹1,86,405 करोड़) 2032-33 तक 135 GW तक नवीकरणीय ऊर्जा के लिए राज्यों के भीतर ट्रांसमिशन मज़बूत करेगी और 50 GWh बैटरी भंडारण जोड़ेगी।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Railways", "q": "In the Union Budget 2026-27, the total capital expenditure planned for Indian Railways is about:", "o": ["₹2.52 lakh crore", "₹2.93 lakh crore", "₹1.20 lakh crore", "₹3.50 lakh crore"], "a": 1, "e": "Railways' total capex for 2026-27 is ₹2,93,030 crore, with a budget outlay of ₹2,78,030 crore; ₹1.2 lakh crore is earmarked for safety.", "qh": "केंद्रीय बजट 2026-27 में भारतीय रेलवे के लिए कुल पूंजीगत व्यय लगभग कितना रखा गया है?", "oh": ["₹2.52 लाख करोड़", "₹2.93 लाख करोड़", "₹1.20 लाख करोड़", "₹3.50 लाख करोड़"], "eh": "2026-27 में रेलवे का कुल पूंजीगत व्यय ₹2,93,030 करोड़ है, बजट आवंटन ₹2,78,030 करोड़; सुरक्षा के लिए ₹1.2 लाख करोड़ अलग रखे गए हैं।", "level": "tough"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Which Article of the Constitution provides for the Attorney General of India?", "o": ["Article 76", "Article 148", "Article 165", "Article 124"], "a": 0, "e": "Article 76 provides for the Attorney General; Article 165 provides for the Advocate General of a state.", "qh": "भारत के महान्यायवादी (अटॉर्नी जनरल) का प्रावधान संविधान के किस अनुच्छेद में है?", "oh": ["अनुच्छेद 76", "अनुच्छेद 148", "अनुच्छेद 165", "अनुच्छेद 124"], "eh": "अनुच्छेद 76 महान्यायवादी का है; अनुच्छेद 165 राज्य के महाधिवक्ता का है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "How many players does a kabaddi team have on the mat at a time?", "o": ["7", "6", "9", "11"], "a": 0, "e": "Each kabaddi side fields 7 players on court (with substitutes on the bench).", "qh": "कबड्डी में एक टीम के एक समय में मैदान पर कितने खिलाड़ी होते हैं?", "oh": ["7", "6", "9", "11"], "eh": "कबड्डी में हर टीम के 7 खिलाड़ी मैदान पर होते हैं (बाकी बदले जाने वाले खिलाड़ी बेंच पर)।", "level": "easy"}, {"s": "General Awareness and Current Affairs", "t": "Sports", "q": "At the Glasgow 2026 Commonwealth Games, Mirabai Chanu won gold in which weightlifting category, her third straight CWG title?", "o": ["Women's 49 kg", "Women's 48 kg", "Women's 55 kg", "Women's 53 kg"], "a": 1, "e": "Mirabai lifted a Games-record 190 kg (85 + 105) in the women's 48 kg on 26 July 2026. (CWG Glasgow: 23 July–2 August 2026; India 4th with 39 medals.)", "qh": "ग्लासगो 2026 राष्ट्रमंडल खेलों में मीराबाई चानू ने किस भारोत्तोलन वर्ग में स्वर्ण जीता, जो उनका लगातार तीसरा CWG खिताब था?", "oh": ["महिला 49 kg", "महिला 48 kg", "महिला 55 kg", "महिला 53 kg"], "eh": "मीराबाई ने 26 जुलाई 2026 को महिला 48 kg में खेलों का रिकॉर्ड 190 kg (85 + 105) उठाया। (ग्लासगो CWG: 23 जुलाई–2 अगस्त 2026; भारत 39 पदकों के साथ चौथा।)", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Polity", "q": "Which Fundamental Right did Dr B. R. Ambedkar call the 'heart and soul' of the Constitution?", "o": ["Right to Constitutional Remedies", "Right to Equality", "Right to Freedom of Religion", "Right against Exploitation"], "a": 0, "e": "Ambedkar described Article 32, the Right to Constitutional Remedies, as the heart and soul of the Constitution.", "qh": "डॉ. बी. आर. आंबेडकर ने किस मौलिक अधिकार को संविधान का 'हृदय और आत्मा' कहा?", "oh": ["संवैधानिक उपचारों का अधिकार", "समानता का अधिकार", "धर्म की स्वतंत्रता का अधिकार", "शोषण के विरुद्ध अधिकार"], "eh": "आंबेडकर ने अनुच्छेद 32, यानी संवैधानिक उपचारों के अधिकार, को संविधान का हृदय और आत्मा कहा।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Awards", "q": "The Jnanpith Award is given for outstanding contribution to:", "o": ["Cinema", "Music", "Literature", "Science"], "a": 2, "e": "The Jnanpith, given by the Bharatiya Jnanpith trust since 1965, is India's highest literary award.", "qh": "ज्ञानपीठ पुरस्कार किस क्षेत्र में उत्कृष्ट योगदान के लिए दिया जाता है?", "oh": ["सिनेमा", "संगीत", "साहित्य", "विज्ञान"], "eh": "भारतीय ज्ञानपीठ ट्रस्ट द्वारा 1965 से दिया जाने वाला ज्ञानपीठ भारत का सर्वोच्च साहित्यिक पुरस्कार है।", "level": "medium"}, {"s": "General Awareness and Current Affairs", "t": "Geography", "q": "The Sardar Sarovar Dam is built on which river?", "o": ["Tapi", "Mahi", "Narmada", "Sabarmati"], "a": 2, "e": "The Sardar Sarovar Dam on the Narmada is at Kevadia (Ekta Nagar), Gujarat, near the Statue of Unity.", "qh": "सरदार सरोवर बाँध किस नदी पर बना है?", "oh": ["तापी", "माही", "नर्मदा", "साबरमती"], "eh": "नर्मदा पर सरदार सरोवर बाँध गुजरात के केवड़िया (एकता नगर) में स्टैच्यू ऑफ़ यूनिटी के पास है।", "level": "medium"}]});
